    private static var cache: [AddTunnelKind: NSImage] = [:]

    /// The logo in its brand color, or nil when there is none.
    static func image(for kind: AddTunnelKind) -> NSImage? {
        if let cached = cache[kind] { return cached }
        guard let logo = logos[kind] else { return nil }
        let svg = "<svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\">"
            + "<path fill=\"#\(logo.hex)\" d=\"\(logo.path)\"/></svg>"
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        cache[kind] = image
        return image
    }

    static func inset(for kind: AddTunnelKind) -> CGFloat { logos[kind]?.inset ?? 0.17 }

    static func color(for kind: AddTunnelKind) -> NSColor? {
        guard let hex = logos[kind]?.hex, let value = UInt32(hex, radix: 16) else { return nil }
        return NSColor(srgbRed: CGFloat((value >> 16) & 0xFF) / 255, green: CGFloat((value >> 8) & 0xFF) / 255,
                       blue: CGFloat(value & 0xFF) / 255, alpha: 1)
    }
